#include <cstdio>
#include <filesystem>
#include <format>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string_view>
#include <system_error>
#include <utility>

// Creates a uniquely named file in `dir` and removes it when the object is destroyed, unless
// keep() was called first. Non-copyable: two owners would race to delete the same path.
class ScratchFile {
 public:
  ScratchFile(const std::filesystem::path& dir, std::string_view prefix)
      : path_(dir / std::format("{}_{}.tmp", prefix, next_id())), handle_(std::fopen(path_.c_str(), "w")) {
    if (!handle_) throw std::runtime_error("cannot create " + path_.string());
  }
  ~ScratchFile() { release(); }

  ScratchFile(const ScratchFile&) = delete;
  ScratchFile& operator=(const ScratchFile&) = delete;
  ScratchFile(ScratchFile&&) noexcept = default;
  ScratchFile& operator=(ScratchFile&& other) noexcept {
    if (this != &other) {
      release();
      path_ = std::move(other.path_);
      handle_ = std::move(other.handle_);
      keep_ = other.keep_;
    }
    return *this;
  }

  void write_line(std::string_view text) { std::fputs(std::format("{}\n", text).c_str(), handle_.get()); }
  void keep() noexcept { keep_ = true; }
  [[nodiscard]] const std::filesystem::path& path() const { return path_; }

 private:
  static std::ptrdiff_t next_id() {
    static std::ptrdiff_t id = 0;
    return id++;
  }

  // Closes the handle and, unless keep_ was set, removes the file. A moved-from object has no
  // handle left, so this is a no-op for it.
  void release() noexcept {
    if (!handle_) return;
    handle_.reset();
    if (!keep_) {
      std::error_code ec;
      std::filesystem::remove(path_, ec);
    }
  }

  struct Closer {
    void operator()(std::FILE* f) const noexcept { std::fclose(f); }
  };
  std::filesystem::path path_;
  std::unique_ptr<std::FILE, Closer> handle_;
  bool keep_ = false;
};

void copy_into(ScratchFile& target, ScratchFile& source) { target = std::move(source); }

void create_then_throw(const std::filesystem::path& dir) {
  ScratchFile scratch(dir, "aborted");
  scratch.write_line("partial");
  throw std::runtime_error("build step failed");
}

int main() {
  const std::filesystem::path dir = std::filesystem::temp_directory_path();

  // 1. The file exists while the object is alive, and is gone once it is destroyed.
  std::filesystem::path first_path;
  {
    ScratchFile scratch(dir, "proof");
    scratch.write_line("hello");
    first_path = scratch.path();
    std::cout << std::format("1 exists while alive: {}\n", std::filesystem::exists(first_path));
  }
  std::cout << std::format("1 gone after scope: {}\n", !std::filesystem::exists(first_path));

  // 2. An exception in flight still removes the file it was writing.
  try {
    create_then_throw(dir);
  } catch (const std::runtime_error& e) {
    std::cout << std::format("2 caught: {}\n", e.what());
  }

  // 3. keep() survives destruction, and the test cleans up after itself.
  std::filesystem::path kept_path;
  {
    ScratchFile scratch(dir, "kept");
    scratch.write_line("keep me");
    kept_path = scratch.path();
    scratch.keep();
  }
  std::cout << std::format("3 kept after scope: {}\n", std::filesystem::exists(kept_path));
  std::filesystem::remove(kept_path);

  // 4. Moving transfers ownership: destroying the moved-from source first leaves the file alone.
  std::filesystem::path moved_path;
  {
    ScratchFile a(dir, "move-src");
    moved_path = a.path();
    {
      ScratchFile b(std::move(a));
      std::cout << std::format("4 file survives the moved-from source's destructor: {}\n",
                               std::filesystem::exists(moved_path));
    }
  }
  std::cout << std::format("4 gone once the owner is destroyed: {}\n", !std::filesystem::exists(moved_path));

  // 5. Move-assigning onto a live scratch file removes the one it held, not just the one it takes.
  ScratchFile c(dir, "c");
  ScratchFile d(dir, "d");
  const std::filesystem::path path_c = c.path();
  const std::filesystem::path path_d = d.path();
  d = std::move(c);  // d's own file must go, or the assessment leaves it behind on disk
  std::cout << std::format("5 old d file removed by the assignment: {}\n", !std::filesystem::exists(path_d));
  std::cout << std::format("5 d now owns c's file: {}\n", d.path() == path_c);

  copy_into(d, d);  // self-move-assignment through two references
  std::cout << std::format("5 self-move-assignment left the file in place: {}\n", std::filesystem::exists(path_c));

  std::error_code ec;
  std::filesystem::remove(path_c, ec);
}

#include <condition_variable>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
#include <mutex>
#include <optional>
#include <stop_token>
#include <utility>

// A queue with room for `capacity` items. Each call to push or pop carries its own stop token, so
// one caller can be cancelled without affecting any other: there is no queue-wide closed flag.
template <typename T>
class CancellableQueue {
 public:
  explicit CancellableQueue(std::ptrdiff_t capacity) : capacity_(capacity) {}

  // False once `stop` fires before room appears; otherwise it waits for room and hands the item over.
  [[nodiscard]] bool push(T item, std::stop_token stop) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (!not_full_.wait(lock, stop, [this] { return std::ssize(items_) < capacity_; })) return false;
    items_.push_back(std::move(item));
    lock.unlock();
    not_empty_.notify_one();
    return true;
  }

  // No value once `stop` fires and the queue is empty; otherwise it waits for an item and takes it.
  // An item already waiting is handed over even if `stop` has already fired.
  [[nodiscard]] std::optional<T> pop(std::stop_token stop) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (!not_empty_.wait(lock, stop, [this] { return !items_.empty(); })) return std::nullopt;
    T item = std::move(items_.front());
    items_.pop_front();
    lock.unlock();
    not_full_.notify_one();
    return item;
  }

  [[nodiscard]] std::ptrdiff_t size() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return std::ssize(items_);
  }

 private:
  mutable std::mutex mutex_;
  std::condition_variable_any not_full_;   // waited on by pushers: there is room, or stop fired
  std::condition_variable_any not_empty_;  // waited on by poppers: there is an item, or stop fired
  std::deque<T> items_;
  std::ptrdiff_t capacity_ = 0;
};

int main() {
  CancellableQueue<std::int64_t> q(2);
  std::stop_source never;  // its token is never stopped

  std::cout << std::format("push 1: {}\n", q.push(1, never.get_token()));
  std::cout << std::format("push 2: {}\n", q.push(2, never.get_token()));

  std::stop_source already_stopped;
  already_stopped.request_stop();
  std::cout << std::format("push 3 into a full queue with a stopped token: {}\n",
                           q.push(3, already_stopped.get_token()));

  std::cout << std::format("pop gives {}\n", q.pop(never.get_token()).value());
  std::cout << std::format("push 3 now there is room: {}\n", q.push(3, never.get_token()));
  std::cout << std::format("size: {}\n", q.size());

  // Draining: an item already waiting is handed over even to a stopped token.
  CancellableQueue<std::int64_t> drain(4);
  [[maybe_unused]] const bool filled = drain.push(9, never.get_token());
  std::stop_source stop_now;
  stop_now.request_stop();
  std::cout << std::format("pop with a stopped token but an item waiting: {}\n",
                           drain.pop(stop_now.get_token()).value());
  std::cout << std::format("pop again, now empty and stopped: {}\n", drain.pop(stop_now.get_token()).has_value());
}

#include <algorithm>
#include <condition_variable>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
