#include <numeric>
#include <optional>
#include <ranges>
#include <stop_token>
#include <thread>
#include <utility>
#include <vector>

template <typename T>
class CancellableQueue {
 public:
  explicit CancellableQueue(std::ptrdiff_t capacity) : capacity_(capacity) {}

  [[nodiscard]] bool push(T item, std::stop_token stop) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (!not_full_.wait(lock, stop, [this] { return std::ssize(items_) < capacity_; })) return false;
    items_.push_back(std::move(item));
    lock.unlock();
    not_empty_.notify_one();
    return true;
  }

  [[nodiscard]] std::optional<T> pop(std::stop_token stop) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (!not_empty_.wait(lock, stop, [this] { return !items_.empty(); })) return std::nullopt;
    T item = std::move(items_.front());
    items_.pop_front();
    lock.unlock();
    not_full_.notify_one();
    return item;
  }

  [[nodiscard]] std::ptrdiff_t size() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return std::ssize(items_);
  }

 private:
  mutable std::mutex mutex_;
  std::condition_variable_any not_full_;
  std::condition_variable_any not_empty_;
  std::deque<T> items_;
  std::ptrdiff_t capacity_ = 0;
};

constexpr std::int64_t kProducers = 3;
constexpr std::int64_t kConsumers = 3;
constexpr std::int64_t kPerProducer = 300;

struct Command {
  std::int64_t id = 0;
};

int main() {
  constexpr std::ptrdiff_t kCapacity = 4;
  CancellableQueue<Command> queue(kCapacity);
  std::vector<std::vector<std::int64_t>> received(kConsumers);
  std::stop_source consumer_stop;  // requested only once every producer is done
  std::ptrdiff_t high_water = 0;
  {
    std::jthread watcher([&queue, &high_water] {
      for (int k = 0; k < 50'000; ++k) high_water = std::max(high_water, queue.size());
    });
    std::vector<std::jthread> consumers;
    consumers.reserve(kConsumers);
    for (std::int64_t c = 0; c < kConsumers; ++c) {
      consumers.emplace_back([&queue, &consumer_stop, mine = &received[c]] {
        while (const std::optional<Command> command = queue.pop(consumer_stop.get_token())) {
          mine->push_back(command.value().id);
        }
      });
    }
    {
      std::vector<std::jthread> producers;
      producers.reserve(kProducers);
      for (std::int64_t p = 0; p < kProducers; ++p) {
        producers.emplace_back([&queue, p] {
          for (std::int64_t k = 0; k < kPerProducer; ++k) {
            [[maybe_unused]] const bool ok = queue.push({.id = p * kPerProducer + k}, std::stop_token{});
          }
        });
      }
    }  // every producer has finished pushing
    consumer_stop.request_stop();  // let the consumers drain what is left, then stop
  }

  std::vector<std::int64_t> all;
  for (const std::vector<std::int64_t>& mine : received) all.insert(all.end(), mine.begin(), mine.end());
  std::ranges::sort(all);
  const std::int64_t expected = kProducers * kPerProducer;
  std::vector<std::int64_t> wanted(static_cast<std::size_t>(expected));
  std::iota(wanted.begin(), wanted.end(), 0);
  std::cout << std::format("{} commands sent, {} received, queue left with {}\n", expected, std::ssize(all),
                           queue.size());
  std::cout << std::format("every command exactly once: {}\n", all == wanted);
  std::cout << std::format("a watcher sampled the size 50000 times and never saw more than {}: {}\n", kCapacity,
                           high_water <= kCapacity);
}
